import { defineConfig } from 'vite';
import { createHash } from 'crypto';
import { readdirSync, readFileSync, statSync } from 'fs';
import path from 'path';

// Static assets are served from web/public/ — WebP-optimised copies of ../export/
// generated by `npm run optimize-assets`.
//
// Their URLs get `?v=<hash of public/>` so the server can cache them as immutable:
// re-running optimize-assets changes the hash and busts every cached copy.
function hashDir(dir) {
  const h = createHash('sha256');
  const walk = (d) =>
    readdirSync(d)
      .sort()
      .forEach((name) => {
        const p = path.join(d, name);
        if (statSync(p).isDirectory()) walk(p);
        else h.update(name).update(readFileSync(p));
      });
  walk(dir);
  return h.digest('hex').slice(0, 10);
}

export default defineConfig({
  define: {
    __ASSET_VERSION__: JSON.stringify(hashDir(path.resolve(__dirname, 'public'))),
  },
  server: {
    port: 5173,
    open: false,
  },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    chunkSizeWarningLimit: 600, // three.js alone is ~530 kB minified
    rollupOptions: {
      output: {
        // three.js changes far less often than game code: separate chunk = better caching
        manualChunks: {
          three: ['three'],
        },
      },
    },
  },
});
